import { Color, MeshStandardMaterial } from "three";

/**
 * Standard PBR material with procedural muscle-fibre striations.
 * Expects UVs where u counts fibres around the muscle and v is metres along it
 * (generated by tools/anatomy/build_figure.py).
 */
export function createFibreMaterial(options: {
  color: string;
  roughness: number;
  fibreStrength: number;
  emissive?: string;
}): MeshStandardMaterial {
  const material = new MeshStandardMaterial({
    color: new Color(options.color),
    roughness: options.roughness,
    metalness: 0,
    emissive: new Color(options.emissive ?? "#000000"),
    emissiveIntensity: options.emissive ? 0.2 : 0,
  });
  material.defines = { ...material.defines, USE_UV: "" };
  const strength = { value: options.fibreStrength };

  material.onBeforeCompile = (shader) => {
    shader.uniforms.uFibreStrength = strength;
    shader.fragmentShader = shader.fragmentShader
      .replace(
        "#include <common>",
        /* glsl */ `#include <common>
uniform float uFibreStrength;
float fibreHash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float fibreNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(fibreHash(i), fibreHash(i + vec2(1.0, 0.0)), u.x),
             mix(fibreHash(i + vec2(0.0, 1.0)), fibreHash(i + vec2(1.0, 1.0)), u.x), u.y);
}
// u: fibre index around the muscle, v: metres along it.
// Each band fades out before it reaches one cycle per two pixels, so distant or
// densely-unwrapped muscles go smooth instead of aliasing into stripes.
float bandFade(float cyclesPerPixel) { return 1.0 - smoothstep(0.12, 0.4, cyclesPerPixel); }
float fibreHeight(vec2 uv, vec2 fw, out float fade) {
  float wobble = fibreNoise(vec2(uv.x * 0.2, uv.y * 14.0)) * 1.2;
  float bundleFade = bandFade(fw.x + fw.y * 14.0 * 1.2);
  float grainFade = bandFade(max(fw.x * 2.7, fw.y * 120.0));
  float bundles = mix(0.5, 0.5 + 0.5 * sin(6.2831853 * (uv.x + wobble)), bundleFade);
  float grain = mix(0.5, fibreNoise(vec2(uv.x * 2.7, uv.y * 120.0)), grainFade);
  fade = max(bundleFade, grainFade);
  return bundles * 0.7 + grain * 0.3;
}
vec3 fibrePerturb(vec3 surfPos, vec3 surfNorm, vec2 dHdxy, float faceDir) {
  vec3 sigmaX = dFdx(surfPos);
  vec3 sigmaY = dFdy(surfPos);
  vec3 r1 = cross(sigmaY, surfNorm);
  vec3 r2 = cross(surfNorm, sigmaX);
  float det = dot(sigmaX, r1) * faceDir;
  vec3 grad = sign(det) * (dHdxy.x * r1 + dHdxy.y * r2);
  return normalize(abs(det) * surfNorm - grad);
}`,
      )
      .replace(
        "#include <color_fragment>",
        /* glsl */ `#include <color_fragment>
float fibreFade;
float fibreH = fibreHeight(vUv, fwidth(vUv), fibreFade);
diffuseColor.rgb *= mix(1.0, 0.94 + 0.12 * fibreH, fibreFade);`,
      )
      .replace(
        "#include <normal_fragment_maps>",
        /* glsl */ `#include <normal_fragment_maps>
vec2 fibreGrad = vec2(dFdx(fibreH), dFdy(fibreH)) * uFibreStrength * fibreFade;
normal = fibrePerturb(-vViewPosition, normal, fibreGrad, faceDirection);`,
      );
  };
  material.customProgramCacheKey = () => "spotter-fibre";
  return material;
}
